package com.coraline.feast;
import com.coraline.otherworld.*;
import com.coraline.registry.ModItems;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraftforge.gametest.*;
import java.util.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class ExpeditionGameTests {
    record Fixture(ServerPlayer p,VisitData.Scene s,BlockPos c){}
    static Fixture fixture(GameTestHelper h,OtherMotherActivities.Activity a){var l=h.getLevel().getServer().getLevel(ActivityWorld.KEY);var p=FakePlayerFactory.get(l,new GameProfile(UUID.randomUUID(),"ExpeditionQA"));var door=new DoorData.Door();door.owner=p.getUUID();door.pos=new BlockPos(68000,80,68000);DoorData.get(p.server).doors.put(door.id,door);var realm=RealmData.get(p.server).realm(door);realm.ready=true;realm.parentGeneration=1;
        var s=new VisitData.Scene();s.owner=p.getUUID();s.door=door.id;s.stage=VisitData.Stage.DONE;s.table=realm.doorPos;s.piano=realm.doorPos;s.loop.phase=OtherMotherLoopState.Phase.ACTIVITY;s.loop.activity=a;s.loop.generation=1;s.loop.expedition.putLong("Seed",8923);VisitData.get(p.server).scenes.put(s.owner,s);p.getPersistentData().putUUID("CoralineVisitDoor",s.door);var c=ExpeditionActivities.center(p,s);p.setPos(Vec3.atBottomCenterOf(c));return new Fixture(p,s,c);}
    @GameTest(template="empty") public static void mansionThousandUniqueSolvablePuzzles(GameTestHelper h){var distinct=new HashSet<String>();for(int seed=0;seed<1000;seed++){var p=MansionPuzzle.generate(seed);h.assertTrue(p.rooms().size()==12&&p.clues().size()==6,"Missing candidates/clues");h.assertTrue(p.solve()==1<<p.jackpot(),"Not exactly one solution");distinct.add(p.rooms().toString()+p.clues());for(var c:p.clues())h.assertTrue(Integer.bitCount(c.mask())>=9,"Overly revealing clue");for(int bits=0;bits<64;bits++)if(Integer.bitCount(bits)<=4){int m=4095;for(int i=0;i<6;i++)if((bits&(1<<i))!=0)m&=p.clues().get(i).mask();h.assertTrue(Integer.bitCount(m)>1,"Four clues solve the mansion");}}h.assertTrue(distinct.size()==1000,"Repeated puzzle layouts");h.succeed();}
    @GameTest(template="empty") public static void mineVarietyAndDepth(GameTestHelper h){long shallow=0,deep=0;for(int seed=0;seed<1000;seed++){var plan=MineshaftActivity.generate(seed);h.assertTrue(plan.rooms().size()==420&&plan.ores().size()>400,"Mine too small");var seen=new HashSet<BlockPos>();for(var ore:plan.ores()){h.assertTrue(seen.add(ore.offset()),"Overlapping deposits");h.assertTrue(ore.ticks()>=6&&ore.ticks()<=22,"Unfair mining time");if(ore.tier()==0)shallow+=ore.kind();if(ore.tier()==3)deep+=ore.kind();}}h.assertTrue(deep>shallow*2,"Depth does not improve loot");h.succeed();}
    @GameTest(template="empty") public static void fortressThousandReachableCourses(GameTestHelper h){var distinct=new HashSet<String>();for(int seed=0;seed<1000;seed++){var gates=FortressActivity.generate(seed);h.assertTrue(gates.size()==7,"Wrong module count");distinct.add(gates.toString());int x=0,z=-1;for(var g:gates){h.assertTrue(Math.abs(g.x()-x)<=6&&Math.abs(g.z()-z)<=6,"Gap cannot be reached");h.assertTrue(FortressActivity.inside(g,g.x()+.5,g.z()+.5),"Center not safe");h.assertTrue(!FortressActivity.inside(g,g.x()+g.radius()+1,g.z()),"Obstacle accepted");x=g.x();z=g.z();}}h.assertTrue(distinct.size()>990,"Repeated fortress course");h.succeed();}
    @GameTest(template="empty",timeoutTicks=600) public static void mineGeometryAndPayoutOnce(GameTestHelper h){var f=fixture(h,OtherMotherActivities.Activity.OTHER_MINESHAFT);var p=f.p;var s=f.s;var c=f.c;var l=p.serverLevel();MineshaftActivity.build(p,s,l,c);var plan=MineshaftActivity.generate(s.loop.expedition.getLong("Seed"));
        for(var candidate:plan.ores()){var ore=MineshaftActivity.eligible(candidate,s.loop.expedition);var at=c.offset(ore.offset());h.assertTrue(l.getBlockState(at).is(MineshaftActivity.BLOCKS[ore.kind()]),"Missing deposit");boolean exposed=false;for(var direction:Direction.Plane.HORIZONTAL)if(l.isEmptyBlock(at.relative(direction)))exposed=true;h.assertTrue(exposed,"Inaccessible ore");}
        s.loop.expedition.putInt("Phase",1);MineshaftActivity.begin(p,s);var ore=plan.ores().get(0);MineshaftActivity.harvest(p,s,c.offset(ore.offset()),ore);MineshaftActivity.harvest(p,s,c.offset(ore.offset()),ore);h.assertTrue(s.loop.expedition.getInt("Count")==1,"Duplicate ore reward");p.setPos(Vec3.atBottomCenterOf(c.south(7)));MineshaftActivity.settle(p,s);ExpeditionActivities.restore(p,s);MineshaftActivity.deliver(p);int count=p.getInventory().countItem(MineshaftActivity.loot(ore.kind()));MineshaftActivity.settle(p,s);MineshaftActivity.deliver(p);h.assertTrue(count==1&&p.getInventory().countItem(MineshaftActivity.loot(ore.kind()))==1,"Bag paid twice");h.assertTrue(!p.getInventory().contains(new ItemStack(ModItems.ACTIVITY_MINING_PICK.get())),"Temporary pick retained");h.succeed();}
    @GameTest(template="empty",timeoutTicks=600) public static void fortressActualOpenings(GameTestHelper h){var f=fixture(h,OtherMotherActivities.Activity.OTHER_NETHER_FORTRESS);var l=f.p.serverLevel();FortressActivity.build(f.p,f.s,l,f.c);for(var g:FortressActivity.generate(f.s.loop.expedition.getLong("Seed")))h.assertTrue(l.isEmptyBlock(f.c.offset(g.x(),g.y(),g.z())),"Authored prop blocks route waypoint");var pool=FortressDropper.pool(f.s.loop.expedition.getLong("Seed"),0);h.assertTrue(l.getBlockState(f.c.offset(pool.x(),-279,pool.z())).is(Blocks.LAVA),"Landing pool missing");h.succeed();}
    @GameTest(template="empty",timeoutTicks=600) public static void mansionDoorsKeyAndHelpers(GameTestHelper h){var f=fixture(h,OtherMotherActivities.Activity.OTHER_WOODLAND_MANSION);var p=f.p;var s=f.s;var l=p.serverLevel();MansionActivity.build(p,s,l,f.c);var game=MansionActivity.puzzle(s);for(var r:game.rooms()){var at=MansionActivity.door(f.c,r);h.assertTrue(l.getBlockState(at).is(Blocks.IRON_DOOR),"Candidate not locked");h.assertTrue(l.isEmptyBlock(at.offset(-MansionActivity.side(r),1,0)),"Door inaccessible");}s.loop.expedition.putInt("Phase",1);MansionActivity.begin(p,s);var helper=FakePlayerFactory.get(l,new GameProfile(UUID.randomUUID(),"MansionHelper"));helper.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,p.getMainHandItem().copy());h.assertTrue(!MansionActivity.choose(helper,s,game.jackpot()),"Helper spent key");int wrong=(game.jackpot()+1)%12;h.assertTrue(MansionActivity.choose(p,s,wrong),"Valid key failed");h.assertTrue(s.loop.expedition.getInt("Phase")==5&&ActivityWorld.exitReady(s),"Wrong room softlock");h.assertTrue(!MansionActivity.choose(p,s,game.jackpot()),"Second door opened");h.succeed();}
    @GameTest(template="empty") public static void expeditionLedgerPersistence(GameTestHelper h){var state=new OtherMotherLoopState();state.expedition.putInt("Phase",3);state.expedition.putInt("Clues",27);state.expedition.putLong("Seed",723456L);state.expedition.put("Stored",new ItemStack(Items.DIAMOND,5).save(new CompoundTag()));var copy=OtherMotherLoopState.load(state.save());h.assertTrue(copy.expedition.equals(state.expedition),"Lost durable activity state");h.succeed();}
}
